import numpy as np

def contact_wrenches(points, normals, mu, rho):
    """points, normals: lists of (x, y); normals point into the object (normalise them).
    Return an array with one row (fx, fy, torque / rho) per friction-cone edge: two edges per contact,
    n + mu*t and n - mu*t with t = (-n_y, n_x), or just n per contact if mu == 0."""
    return np.zeros((len(points), 3))

exercises.reference:
import numpy as np

def contact_wrenches(points, normals, mu, rho):
    W = []
    for p, n in zip(np.asarray(points, float), np.asarray(normals, float)):
        n = n / np.linalg.norm(n)
        t = np.array([-n[1], n[0]])
        forces = (n + mu * t, n - mu * t) if mu > 0 else (n,)
        for f in forces:
            W.append([f[0], f[1], (p[0] * f[1] - p[1] * f[0]) / rho])
    return np.array(W)
